ALTER POLICY "own events" ON public.planner_events WITH CHECK (user_id = auth.uid() AND (outfit_id IS NULL OR EXISTS (SELECT 1 FROM public.outfits o WHERE o.id = outfit_id AND o.user_id = auth.uid())));
ALTER POLICY "own feedback" ON public.feedback WITH CHECK (user_id = auth.uid() AND (outfit_id IS NULL OR EXISTS (SELECT 1 FROM public.outfits o WHERE o.id = outfit_id AND o.user_id = auth.uid())) AND NOT EXISTS (SELECT 1 FROM unnest(item_ids) AS requested(id) WHERE NOT EXISTS (SELECT 1 FROM public.wardrobe_items w WHERE w.id = requested.id AND w.user_id = auth.uid())));
ALTER POLICY "own items" ON public.wardrobe_items WITH CHECK (user_id = auth.uid() AND (image_path IS NULL OR split_part(image_path, '/', 1) = auth.uid()::text));
ALTER POLICY "own trips" ON public.trips WITH CHECK (user_id = auth.uid() AND NOT EXISTS (SELECT 1 FROM unnest(item_ids) AS requested(id) WHERE NOT EXISTS (SELECT 1 FROM public.wardrobe_items w WHERE w.id = requested.id AND w.user_id = auth.uid())) AND NOT EXISTS (SELECT 1 FROM unnest(outfit_ids) AS requested(id) WHERE NOT EXISTS (SELECT 1 FROM public.outfits o WHERE o.id = requested.id AND o.user_id = auth.uid())));